INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:kiro:cli-surface-v1','project_tool','seed://kiro/cli-surface','Kiro CLI command surface','Snapshot date: 2026-07-15. Commands and tools: kiro-cli agent list, create, edit; kiro-cli chat; --agent, --verbose/-v, --version/-V, --help, --help-all; custom agents and steering. Configuration model: ~/.kiro/settings/mcp.json, .kiro/agents/, .kiro/steering/; project configuration is additive. Source: https://kiro.dev/docs/cli/reference/cli-commands/ (verified 2026-07-15).','https://kiro.dev/docs/cli/reference/cli-commands/ (verified 2026-07-15)','1e2080436bc25c71f652f1fbdb9e065cc02ad9b5731b377caed89a000cfc0ae4','kiro,cli,command-surface,provenance',2.2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:kiro:config-model-v1','project_doc','seed://kiro/config-model','Kiro CLI command surface configuration model','Snapshot date: 2026-07-15. Canonical configuration paths: ~/.kiro/settings/mcp.json, .kiro/agents/, .kiro/steering/; project configuration is additive. Registration is additive, idempotent, and must preserve user-owned keys, hooks, rules, and MCP servers. Source: https://kiro.dev/docs/cli/reference/cli-commands/ (verified 2026-07-15).','https://kiro.dev/docs/cli/reference/cli-commands/ (verified 2026-07-15)','58bd7e10010e96b91624bf514af5c55ce25d2e45c283a750ed9b340ae2fe1381','kiro,config,mcp,rules',2);
INSERT OR IGNORE INTO memory_items(stable_id,kind,source,title,content,artifact_path,source_hash,tags,weight) VALUES('project:kiro:integration-points-v1','project_doc','seed://kiro/integration','Kiro CLI command surface Simplicio integration points','Snapshot date: 2026-07-15. T2 MCP plus rules; settings and agent files must not be clobbered. Simplicio execution remains the governed control plane; provider surfaces are compatibility inputs, not alternate mutation paths. Source: https://kiro.dev/docs/cli/reference/cli-commands/ (verified 2026-07-15).','https://kiro.dev/docs/cli/reference/cli-commands/ (verified 2026-07-15)','0569272f92d16f180ffd59de74cf89acda84a36ab4d23f40c7d6dc899fe8c4b0','kiro,simplicio,integration,governance',2);
